package app.morphe.extension.newx.mediablur;
import android.os.Bundle;import android.view.*;import android.widget.*;import app.morphe.extension.crimera.settings.CustomScreenFragment;
public final class BlurSettingsFragment extends CustomScreenFragment {
 public View onCreateView(LayoutInflater inflater,ViewGroup parent,Bundle state){BlurPreferences.init(getActivity());ScrollView scroll=new ScrollView(getActivity());LinearLayout box=new LinearLayout(getActivity());box.setOrientation(1);int p=(int)(16*getResources().getDisplayMetrics().density);box.setPadding(p,p,p,p);scroll.addView(box);TextView title=new TextView(getActivity());title.setText("In-App Media Blur");title.setTextSize(22);box.addView(title);
 toggle(box,"Activer In-App Media Blur","enabled",true);
 TextView label=new TextView(getActivity());label.setText("Intensité du flou");label.setPadding(0,p,0,0);box.addView(label);
 final String[] values={"light","medium","strong","maximum"};Spinner strength=new Spinner(getActivity());strength.setAdapter(new ArrayAdapter<String>(getActivity(),android.R.layout.simple_spinner_dropdown_item,new String[]{"Légère","Moyenne","Forte","Maximale"}));String current=BlurPreferences.prefs.getString("strength","strong");for(int i=0;i<values.length;i++)if(values[i].equals(current))strength.setSelection(i);box.addView(strength);strength.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){BlurPreferences.prefs.edit().putString("strength",values[pos]).apply();}});
 toggle(box,"Révéler les médias par appui","reveal",true);
 TextView note=new TextView(getActivity());note.setText("Dans le détail d’une publication, appuyer sur Ⓑ pour activer ou désactiver le flou. Le premier appui révèle un média, les suivants conservent son action normale. Les réglages s’appliquent lors du prochain rendu ; rouvrir la publication après modification.");note.setPadding(0,p,0,0);box.addView(note);return scroll;}
 private void toggle(LinearLayout box,String title,final String key,boolean fallback){Switch v=new Switch(getActivity());v.setText(title);v.setChecked(BlurPreferences.prefs.getBoolean(key,fallback));box.addView(v);v.setOnCheckedChangeListener(new CompoundButton.OnCheckedChangeListener(){public void onCheckedChanged(CompoundButton b,boolean value){BlurPreferences.prefs.edit().putBoolean(key,value).apply();}});}
}
